const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'c', tenant: 'a', createdAt: '2026-01-01', total: 4 },
  { id: 'e', tenant: 'a', createdAt: '2026-01-03', total: 5 },
  { id: 'd', tenant: 'a', createdAt: '2026-01-02', total: 6 },
];
const snapshot = JSON.parse(JSON.stringify(rows));
const handler = new OrderHandler(new OrderRepository(rows));

// Filtering + sorting; no cursor behaves like before (slice of sorted filtered list).
const first = handler.list({ tenant: 'a', limit: 2 });
assert.deepEqual(first.items.map(o => o.id), ['a', 'c']);
assert.equal(first.nextCursor, '2026-01-01|c');

// Walk all pages: no repeats, no skips, nextCursor ends as null.
const seen = [];
let cursor;
for (let i = 0; i < 10; i++) {
  const page = handler.list({ tenant: 'a', limit: 2, cursor });
  seen.push(...page.items.map(o => o.id));
  if (page.nextCursor === null) break;
  cursor = page.nextCursor;
}
assert.deepEqual(seen, ['a', 'c', 'b', 'd', 'e']);

// Last page exactly fills the limit -> nextCursor null.
assert.deepEqual(handler.list({ tenant: 'a', limit: 5 }), {
  items: ['a', 'c', 'b', 'd', 'e'].map(id => rows.find(r => r.id === id)),
  nextCursor: null,
});

// Limit boundary inside equal createdAt values.
const equalDates = new OrderHandler(new OrderRepository([
  { id: 'b', tenant: 't', createdAt: 'd', total: 0 },
  { id: 'a', tenant: 't', createdAt: 'd', total: 0 },
  { id: 'c', tenant: 't', createdAt: 'd', total: 0 },
]));
assert.deepEqual(equalDates.list({ tenant: 't', limit: 1 }), {
  items: [{ id: 'a', tenant: 't', createdAt: 'd', total: 0 }],
  nextCursor: 'd|a',
});
assert.deepEqual(equalDates.list({ tenant: 't', limit: 1, cursor: 'd|a' }), {
  items: [{ id: 'b', tenant: 't', createdAt: 'd', total: 0 }],
  nextCursor: 'd|b',
});
assert.deepEqual(equalDates.list({ tenant: 't', limit: 1, cursor: 'd|b' }).items.map(o => o.id), ['c']);

// Cursor row deleted since it was returned: resume strictly after the pair.
const deleted = new OrderHandler(new OrderRepository(rows.filter(r => r.id !== 'c')));
assert.deepEqual(deleted.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|c' }), {
  items: ['b', 'd'].map(id => rows.find(r => r.id === id)),
  nextCursor: '2026-01-02|d',
});

// Cursor pair belonging to another tenant is still just a boundary over tenant 'a'.
const foreign = handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|x' });
assert.deepEqual(foreign.items.map(o => o.id), ['b', 'd', 'e']);
assert.ok(foreign.items.every(o => o.tenant === 'a'));
assert.equal(foreign.nextCursor, null);

// Cursor beyond all matching rows -> empty page, null cursor.
assert.deepEqual(handler.list({ tenant: 'a', limit: 2, cursor: '9999|z' }), { items: [], nextCursor: null });
// Cursor before all matching rows -> starts at the beginning.
assert.deepEqual(handler.list({ tenant: 'a', limit: 1, cursor: '0000|a' }).items.map(o => o.id), ['a']);
// Unknown but well-formed pair is a valid boundary.
assert.deepEqual(handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|bb' }).items.map(o => o.id), ['b', 'd', 'e']);
// Empty tenant result.
assert.deepEqual(handler.list({ tenant: 'zzz', limit: 3 }), { items: [], nextCursor: null });

// Invalid requests.
const invalidRequests = [
  { tenant: '', limit: 1 },
  { tenant: 'a', limit: 0 },
  { tenant: 'a', limit: 101 },
  { tenant: 'a', limit: 1.5 },
  { tenant: 'a', limit: NaN },
  { tenant: 'a', limit: '2' },
  { tenant: 'a', limit: 1, cursor: '' },
  { tenant: 'a', limit: 1, cursor: 'abc' },
  { tenant: 'a', limit: 1, cursor: '|' },
  { tenant: 'a', limit: 1, cursor: 'a|' },
  { tenant: 'a', limit: 1, cursor: '|b' },
  { tenant: 'a', limit: 1, cursor: 'a|b|c' },
  { tenant: 'a', limit: 1, cursor: 'a||b' },
  { tenant: 'a', limit: 1, cursor: null },
  { tenant: 'a', limit: 1, cursor: 42 },
];
for (const request of invalidRequests) {
  assert.throws(() => handler.list(request), err => err instanceof Error && err.message === 'invalid request', JSON.stringify(request));
}

// Repository input array and rows are not mutated.
assert.deepEqual(rows, snapshot);
const repo = new OrderRepository(rows);
repo.list('a');
repo.listPage('a', 2);
repo.listPage('a', 2, '2026-01-01|c');
assert.deepEqual(rows, snapshot);

console.log('pagination checks passed');
EOF
